<?php $title=($user?'Edit':'Add').' User'; require __DIR__.'/partials/header.php'; ?><div class="max-w-xl mx-auto bg-white p-6 rounded shadow"><h2 class="text-2xl font-bold mb-4"><?php echo $title; ?></h2><form method="post"><input class="w-full border p-2 mb-2" name="user" placeholder="Username" required value="<?php echo htmlspecialchars($user['user']??''); ?>"><input class="w-full border p-2 mb-2" name="first_name" placeholder="First name" required value="<?php echo htmlspecialchars($user['first_name']??''); ?>"><input class="w-full border p-2 mb-2" name="last_name" placeholder="Last name" value="<?php echo htmlspecialchars($user['last_name']??''); ?>"><input class="w-full border p-2 mb-2" type="email" name="email" placeholder="Email" required value="<?php echo htmlspecialchars($user['email']??''); ?>"><input class="w-full border p-2 mb-3" type="password" name="password" placeholder="<?php echo $user?'New password (leave blank to keep)':'Password'; ?>" <?php echo $user?'':'required'; ?>><label><input type="checkbox" name="is_admin" <?php echo !empty($user['is_admin'])?'checked':''; ?>> Administrator (all permissions)</label><label class="ml-4"><input type="checkbox" name="is_active" <?php echo !$user||!empty($user['is_active'])?'checked':''; ?>> Active</label><h3 class="font-bold mt-4">Feature permissions</h3><?php foreach($permissions as $key=>$label): ?><label class="block"><input type="checkbox" name="permissions[]" value="<?php echo $key; ?>" <?php echo in_array($key,$selected,true)?'checked':''; ?>> <?php echo $label; ?></label><?php endforeach; ?><button class="mt-5 px-4 py-2 bg-blue-600 text-white rounded">Save User</button></form></div><?php require __DIR__.'/partials/footer.php'; ?>
